const now = new Date().toISOString();
console.log(`🔄 Enhanced Multi-Agent Call Center Analysis Workflow started at ${now}`);

// Initialize batch size and processing limits
const BATCH_SIZE = 5;
const MAX_PROCESSING_TIME_MS = 240000; // 4 minutes

return [{
  json: {
    timestamp: now,
    batch_size: BATCH_SIZE,
    max_processing_time_ms: MAX_PROCESSING_TIME_MS,
    workflow_version: "2.0.0",
    processing_stats: {
      calls_processed: 0,
      successful: 0,
      failed: 0,
      skipped: 0,
      total_processing_time_ms: 0
    }
  }
}];

// Get existing tables from previous node
const existingTables = $input.all().map(item => item.json.table_name);

// Define required tables
const requiredTables = ['llm_analysis', 'calls', 'pipe_response', 'agent_results'];

// Find missing tables
const missingTables = requiredTables.filter(table => !existingTables.includes(table));

if (missingTables.length > 0) {
  console.log(`⚠️ Missing tables detected: ${missingTables.join(', ')}`);
  console.log('⚠️ Please run the Infrastructure Setup and Validation Workflow first');
} else {
  console.log('✅ All required database tables exist');
}

return [{
  json: {
    infrastructure_valid: missingTables.length === 0,
    missing_tables: missingTables,
    timestamp: new Date().toISOString()
  }
}];

// Check for errors in the previous node
const error = $input.first()?.error;

// Get database validation result
const dbValid = $node['Table Existence Processing'].json.infrastructure_valid;

// Check S3 bucket
const s3Valid = !error;

if (!s3Valid) {
  console.log(`⚠️ S3 bucket 'callintech' not accessible: ${error.message}`);
  console.log('⚠️ Please run the Infrastructure Setup and Validation Workflow first');
} else {
  console.log('✅ S3 bucket exists and is accessible');
}

// Overall infrastructure validation
const infrastructureValid = dbValid && s3Valid;

return [{
  json: {
    infrastructure_valid: infrastructureValid,
    db_valid: dbValid,
    s3_valid: s3Valid,
    timestamp: new Date().toISOString()
  }
}];

// Get calls from previous node
const calls = $input.all();

// Check if we have calls to process
if (calls.length === 0) {
  console.log('ℹ️ No unprocessed calls found, workflow will exit');
  return [{
    json: {
      calls_found: false,
      call_count: 0,
      timestamp: new Date().toISOString()
    }
  }];
}

console.log(`ℹ️ Found ${calls.length} unprocessed calls to process`);

// Update processing stats
const processingStats = $node['Workflow Initialization'].json.processing_stats;
processingStats.calls_found = calls.length;

return [{
  json: {
    calls_found: true,
    call_count: calls.length,
    processing_stats: processingStats,
    timestamp: new Date().toISOString()
  }
}];

// Get call data
const call = $input.first().json;

// Format S3 path
const s3Path = `recordings/${call.callid}.mp3`;

console.log(`ℹ️ Processing call ${call.callid} with duration ${call.billsec} seconds`);
console.log(`ℹ️ Downloading recording from S3 path: ${s3Path}`);

// Start processing timer
const processingStartTime = new Date().getTime();

return [{
  json: {
    ...call,
    s3_path: s3Path,
    processing_start_time: processingStartTime
  }
}];

// Get call data and error
const call = $input.first().json;
const error = call.error;

console.log(`❌ Error downloading recording for call ${call.callid}: ${error.message}`);

// Update processing stats
const processingStats = $node['Process Batch Size'].json.processing_stats;
processingStats.failed++;

return [{
  json: {
    ...call,
    error_type: 'S3_DOWNLOAD_ERROR',
    error_message: error.message,
    processing_stats: processingStats
  }
}];

// Get binary data from previous node
const binaryData = $input.first().binary;

// Get call data
const call = $input.first().json;

// Prepare for ElevenLabs API
const audioKey = Object.keys(binaryData)[0];
const audioData = binaryData[audioKey];

console.log(`ℹ️ Sending audio for call ${call.callid} to ElevenLabs STT API`);

return [{
  json: {
    ...call,
    audio_data: audioData
  },
  binary: binaryData
}];

// Get STT response and call data
const sttResponse = $input.first().json;
const call = $input.first().json;

// Check for errors
if (sttResponse.error) {
  console.log(`❌ STT error for call ${call.callid}: ${sttResponse.error}`);

  // Update processing stats
  const processingStats = $node['Process Batch Size'].json.processing_stats;
  processingStats.failed++;

  return [{
    json: {
      ...call,
      error_type: 'STT_ERROR',
      error_message: sttResponse.error,
      processing_stats: processingStats
    }
  }];
}

// Process transcript
const transcript = sttResponse.text;

// Structure conversation (simplified for example)
const structuredConversation = {
  transcript: transcript,
  words: sttResponse.words || [],
  metadata: {
    duration: call.billsec,
    callid: call.callid
  }
};

console.log(`✅ Successfully transcribed call ${call.callid}`);

return [{
  json: {
    ...call,
    conversation: structuredConversation,
    transcript: transcript
  }
}];

// Get transcript
const { transcript, callid } = $input.first().json;

// Simple language detection (would be more sophisticated in production)
const germanWords = ['der', 'die', 'das', 'und', 'ist', 'in', 'zu', 'den', 'für', 'nicht', 'ein', 'mit'];
const germanWordCount = germanWords.reduce((count, word) => {
  const regex = new RegExp(`\\b${word}\\b`, 'gi');
  const matches = transcript.match(regex) || [];
  return count + matches.length;
}, 0);

// Determine language based on German word frequency
const language = germanWordCount > 5 ? 'DE' : 'EN';

console.log(`🔍 Detected language for call ${callid}: ${language}`);

return [{
  json: {
    ...$input.first().json,
    language_detected: language
  }
}];

// Get call data
const callData = $input.first().json;
const { callid, transcript, language_detected } = callData;

// Create agent tasks
const agentTasks = [
  {
    agent_type: 'structure',
    task: 'Analyze conversation structure, identify speakers and roles',
    callid,
    transcript,
    language: language_detected
  },
  {
    agent_type: 'sentiment',
    task: 'Analyze sentiment and emotional tone throughout the conversation',
    callid,
    transcript,
    language: language_detected
  },
  {
    agent_type: 'content',
    task: 'Identify main topics, key terms, and significant points in the conversation',
    callid,
    transcript,
    language: language_detected
  },
  {
    agent_type: 'sales',
    task: 'Evaluate sales process, techniques, and outcomes',
    callid,
    transcript,
    language: language_detected
  },
  {
    agent_type: 'service',
    task: 'Assess customer service quality, politeness, and problem resolution',
    callid,
    transcript,
    language: language_detected
  }
];

console.log(`🔄 Created 5 agent tasks for call ${callid}`);

return [
  {
    json: {
      ...callData,
      agent_tasks: agentTasks,
      agent_count: agentTasks.length
    }
  }
];

// Get agent task
const agentTask = $input.first().json.agent_task;
const { agent_type, language, transcript, callid } = agentTask;

// Base prompt parts
let systemPrompt = '';
let userPrompt = '';

// Select appropriate model based on agent type
let modelSelection = '';

switch (agent_type) {
  case 'structure':
    systemPrompt = `You are a conversation structure analysis expert. Analyze the call transcript to identify speakers, their roles (agent/customer), and the flow of conversation.`;
    userPrompt = `Analyze this call transcript and provide a structured JSON response with speaker identification, role assignment, and conversation flow analysis. Identify who is the call center agent and who is the customer.

Transcript:
${transcript}

Respond with valid JSON only, following this format:
{
  "speakers": [
    {"id": "speaker1", "role": "agent|customer", "confidence": "high|medium|low"},
    {"id": "speaker2", "role": "agent|customer", "confidence": "high|medium|low"}
  ],
  "conversation_flow": {
    "greeting_quality": "excellent|good|poor|missing",
    "turn_taking": "balanced|agent_dominated|customer_dominated",
    "closing_quality": "excellent|good|poor|missing"
  },
  "structure_score": 1-10
}`;
    modelSelection = 'claude';
    break;

  case 'sentiment':
    systemPrompt = `You are an emotion and sentiment analysis expert. Analyze the call transcript to identify emotional tones, sentiment shifts, and overall emotional quality.`;
    userPrompt = `Analyze this call transcript and provide a structured JSON response with sentiment analysis throughout the conversation.

Transcript:
${transcript}

Respond with valid JSON only, following this format:
{
  "overall_sentiment": "positive|neutral|negative",
  "sentiment_score": -1.0 to 1.0,
  "emotional_tone": {
    "beginning": "string",
    "middle": "string",
    "end": "string"
  },
  "sentiment_shifts": [
    {"from": "string", "to": "string", "trigger": "string"}
  ],
  "customer_satisfaction_estimate": 1-10
}`;
    modelSelection = 'claude';
    break;

  case 'content':
    systemPrompt = `You are a content analysis expert. Analyze the call transcript to identify main topics, key terms, and significant points discussed.`;
    userPrompt = `Analyze this call transcript and provide a structured JSON response with content analysis.

Transcript:
${transcript}

Respond with valid JSON only, following this format:
{
  "main_topics": ["string", "string"],
  "key_terms": ["string", "string"],
  "significant_points": ["string", "string"],
  "questions_asked": ["string", "string"],
  "action_items": ["string", "string"],
  "content_relevance_score": 1-10
}`;
    modelSelection = 'openai';
    break;

  case 'sales':
    systemPrompt = `You are a sales process analysis expert. Analyze the call transcript to evaluate sales techniques, objection handling, and outcomes.`;
    userPrompt = `Analyze this call transcript and provide a structured JSON response with sales process analysis.

Transcript:
${transcript}

Respond with valid JSON only, following this format:
{
  "sale_outcome": "successful|unsuccessful|pending",
  "sale_value_scale": 1-10,
  "techniques_used": ["string", "string"],
  "objections_raised": ["string", "string"],
  "objection_handling_quality": "excellent|good|poor|n/a",
  "closing_attempt_quality": "excellent|good|poor|missing",
  "sales_score": 1-10,
  "price_negotiated": true|false,
  "positive_comment_passed_sale": true|false,
  "negative_comment_passed_sale": true|false
}`;
    modelSelection = 'openai';
    break;

  case 'service':
    systemPrompt = `You are a customer service quality analysis expert. Analyze the call transcript to assess politeness, problem resolution, and overall service quality.`;
    userPrompt = `Analyze this call transcript and provide a structured JSON response with service quality analysis.

Transcript:
${transcript}

Respond with valid JSON only, following this format:
{
  "greeting_quality": "excellent|good|poor|missing",
  "problem_resolution": "complete|partial|none|n/a",
  "politeness_score": 1-10,
  "empathy_demonstrated": "high|medium|low|none",
  "customer_addressed_politely": true|false,
  "conversation_fun": true|false,
  "service_advantages_mentioned": true|false,
  "other_platforms_mentioned": true|false,
  "service_score": 1-10
}`;
    modelSelection = 'claude';
    break;

  default:
    systemPrompt = `You are a call analysis expert. Analyze the provided call transcript.`;
    userPrompt = `Analyze this call transcript and provide insights.

Transcript:
${transcript}`;
    modelSelection = 'openai';
}

// Adjust for language if needed
if (language === 'DE') {
  systemPrompt += ' Please analyze in German language context.';
  userPrompt = userPrompt.replace('Analyze this call transcript', 'Analyze this German call transcript');
}

console.log(`🤖 Generated prompt for ${agent_type} agent for call ${callid}`);

return [{
  json: {
    ...agentTask,
    system_prompt: systemPrompt,
    user_prompt: userPrompt,
    model_selection: modelSelection,
    processing_start_time: new Date().getTime()
  }
}];

// Get agent response and task data
const response = $input.first().json;
const agentTask = $input.first().json;
const { agent_type, callid } = agentTask;

// Calculate processing time
const processingEndTime = new Date().getTime();
const processingTime = processingEndTime - agentTask.processing_start_time;

// Initialize result variables
let resultJson = {};
let errorOccurred = false;
let errorMessage = '';

try {
  // Extract result based on LLM provider
  let rawResult = '';

  if (response.choices) {
    // OpenAI format
    rawResult = response.choices[0].message.content;
  } else if (response.content) {
    // Claude format
    rawResult = response.content[0].text;
  } else if (response.candidates) {
    // Gemini format
    rawResult = response.candidates[0].content.parts[0].text;
  } else {
    throw new Error('Unknown response format');
  }

  // Extract JSON from response (handles cases where LLM adds extra text)
  const jsonMatch = rawResult.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    resultJson = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No valid JSON found in response');
  }

  console.log(`✅ Successfully processed ${agent_type} agent result for call ${callid}`);
} catch (error) {
  errorOccurred = true;
  errorMessage = error.message;
  console.log(`❌ Error processing ${agent_type} agent result: ${error.message}`);
}

return [{
  json: {
    callid,
    agent_type,
    result_json: JSON.stringify(resultJson),
    processing_time_ms: processingTime,
    error_occurred: errorOccurred,
    error_message: errorMessage
  }
}];

// Get all agent results
const agentResults = $input.all();

// Get original call data
const callData = $node['Language Detection'].json;
const { callid, language_detected } = callData;

// Organize results by agent type
const resultsByType = {};
let errorCount = 0;

agentResults.forEach(item => {
  const result = item.json;
  resultsByType[result.agent_type] = {
    result: result.result_json ? JSON.parse(result.result_json) : {},
    error: result.error_occurred,
    processing_time: result.processing_time_ms
  };

  if (result.error_occurred) {
    errorCount++;
  }
});

console.log(`ℹ️ Collected results from ${agentResults.length} agents for call ${callid}`);
console.log(`ℹ️ ${errorCount} agents reported errors`);

return [{
  json: {
    ...callData,
    agent_results: resultsByType,
    agent_error_count: errorCount,
    all_agents_completed: true
  }
}];

// Get merged agent results
const { agent_results, callid, transcript, language_detected } = $input.first().json;

// Format agent results for coordinator
const formattedResults = Object.entries(agent_results)
  .map(([type, data]) => {
    return `${type.toUpperCase()} AGENT RESULT:\n${JSON.stringify(data.result, null, 2)}`;
  })
  .join('\n\n');

// Create coordinator system prompt
const systemPrompt = `You are a Coordinator Agent responsible for resolving conflicts and producing a final analysis based on the outputs of multiple specialized agents. Your task is to review the results from all agents, identify any conflicts or inconsistencies, and produce a unified analysis that represents the most accurate understanding of the call.`;

// Create coordinator user prompt
const userPrompt = `Review the following agent results for call ${callid} and produce a unified analysis.

TRANSCRIPT EXCERPT (first 500 chars):
${transcript.substring(0, 500)}...

LANGUAGE: ${language_detected}

${formattedResults}

Based on these agent results, provide a unified analysis in valid JSON format following this structure:
{
  "sentiment": "string",
  "topic": "string",
  "significant_term": "string",
  "general_value": "string",
  "general_experience": "string",
  "email_inquired": "yes|no",
  "positive_comment_passed_sale": "yes|no",
  "negative_comment_passed_sale": "yes|no",
  "price_negotiated": "yes|no",
  "customer_addressed_politely": "yes|no",
  "conversation_fun": "yes|no",
  "service_advantages_mentioned": "yes|no",
  "other_platforms_mentioned": "yes|no",
  "sale_outcome": "string",
  "sale_value_scale": 1-10,
  "asked_if_commenters_known": "yes|no",
  "high_profile_advantages_mentioned": "yes|no",
  "coordination_confidence": "high|medium|low",
  "agent_conflicts_resolved": number
}

Respond with valid JSON only.`;

console.log(`🤖 Generated coordinator prompt for call ${callid}`);

return [{
  json: {
    ...$input.first().json,
    coordinator_system_prompt: systemPrompt,
    coordinator_user_prompt: userPrompt,
    coordinator_start_time: new Date().getTime()
  }
}];

// Get coordinator response
const response = $input.first().json;
const callData = $input.first().json;
const { callid } = callData;

// Calculate processing time
const processingEndTime = new Date().getTime();
const processingTime = processingEndTime - callData.coordinator_start_time;

// Initialize result variables
let finalResult = {};
let errorOccurred = false;
let errorMessage = '';

try {
  // Extract result from Claude response
  let rawResult = '';

  if (response.content) {
    // Claude format
    rawResult = response.content[0].text;
  } else {
    throw new Error('Unknown response format');
  }

  // Extract JSON from response
  const jsonMatch = rawResult.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    finalResult = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No valid JSON found in response');
  }

  console.log(`✅ Successfully processed coordinator result for call ${callid}`);
} catch (error) {
  errorOccurred = true;
  errorMessage = error.message;
  console.log(`❌ Error processing coordinator result: ${error.message}`);
}

// Add language detection to final result
finalResult.language_detected = callData.language_detected;

// Update processing stats
const processingStats = $node['Process Batch Size'].json.processing_stats;
processingStats.successful++;

return [{
  json: {
    ...callData,
    final_result: finalResult,
    coordinator_processing_time_ms: processingTime,
    coordinator_error: errorOccurred,
    coordinator_error_message: errorMessage,
    processing_stats: processingStats
  }
}];

// Get final result and call data
const { final_result, callid, transcript, agent_results } = $input.first().json;

// Create complete analysis object
const completeAnalysis = {
  call_id: callid,
  analysis_timestamp: new Date().toISOString(),
  language_detected: final_result.language_detected,
  transcript_excerpt: transcript.substring(0, 500) + '...',
  coordinator_result: final_result,
  agent_results: agent_results
};

// Format for S3 storage
const analysisJson = JSON.stringify(completeAnalysis, null, 2);

// Generate S3 paths
const analysisS3Path = `analysis/${callid}.json`;
const transcriptS3Path = `transcripts/${callid}.json`;

// Format transcript for S3
const transcriptJson = JSON.stringify({
  call_id: callid,
  transcript: transcript,
  timestamp: new Date().toISOString()
}, null, 2);

console.log(`ℹ️ Preparing to store results for call ${callid}`);

return [{
  json: {
    ...$input.first().json,
    analysis_json: analysisJson,
    transcript_json: transcriptJson,
    analysis_s3_path: analysisS3Path,
    transcript_s3_path: transcriptS3Path
  }
}];

// Get final result and call data
const { final_result, callid } = $input.first().json;

// Format boolean fields for PostgreSQL
const formatBoolean = (value) => {
  if (value === 'yes') return 'true';
  if (value === 'no') return 'false';
  return value === true ? 'true' : 'false';
};

// Create database fields object
const dbFields = {
  call_id: callid,
  sentiment: final_result.sentiment || '',
  topic: final_result.topic || '',
  significant_term: final_result.significant_term || '',
  general_value: final_result.general_value || '',
  general_experience: final_result.general_experience || '',
  email_inquired: formatBoolean(final_result.email_inquired),
  positive_comment_passed_sale: formatBoolean(final_result.positive_comment_passed_sale),
  negative_comment_passed_sale: formatBoolean(final_result.negative_comment_passed_sale),
  price_negotiated: formatBoolean(final_result.price_negotiated),
  customer_addressed_politely: formatBoolean(final_result.customer_addressed_politely),
  conversation_fun: formatBoolean(final_result.conversation_fun),
  service_advantages_mentioned: formatBoolean(final_result.service_advantages_mentioned),
  other_platforms_mentioned: formatBoolean(final_result.other_platforms_mentioned),
  sale_outcome: final_result.sale_outcome || '',
  sale_value_scale: final_result.sale_value_scale || 0,
  asked_if_commenters_known: formatBoolean(final_result.asked_if_commenters_known),
  high_profile_advantages_mentioned: formatBoolean(final_result.high_profile_advantages_mentioned),
  coordination_confidence: final_result.coordination_confidence || 'medium',
  agent_conflicts_resolved: final_result.agent_conflicts_resolved || 0,
  language_detected: final_result.language_detected || 'EN'
};

console.log(`ℹ️ Preparing database update for call ${callid}`);

return [{
  json: {
    ...$input.first().json,
    db_fields: dbFields
  }
}];

// Get all processed calls
const processedCalls = $input.all();

// Get processing stats
const processingStats = $node['Process Batch Size'].json.processing_stats;

// Calculate total processing time
const startTime = new Date($node['Workflow Initialization'].json.timestamp);
const endTime = new Date();
const totalProcessingTimeMs = endTime - startTime;

// Update processing stats
processingStats.total_processing_time_ms = totalProcessingTimeMs;
processingStats.calls_processed = processedCalls.length;

console.log(`✅ Batch processing complete`);
console.log(`📊 Processed ${processingStats.calls_processed} calls in ${totalProcessingTimeMs}ms`);
console.log(`📊 Success: ${processingStats.successful}, Failed: ${processingStats.failed}, Skipped: ${processingStats.skipped}`);

return [{
  json: {
    processing_stats: processingStats,
    completion_timestamp: endTime.toISOString()
  }
}];

// Get processing stats
const { processing_stats } = $input.first().json;

// Format error notification
const errorNotification = {
  subject: `❌ Call Analysis Errors - ${new Date().toISOString()}`,
  body: `
  Call analysis encountered errors:

  Total calls processed: ${processing_stats.calls_processed}
  Successful: ${processing_stats.successful}
  Failed: ${processing_stats.failed}
  Skipped: ${processing_stats.skipped}

  Please check the logs for more details.
  `
};

console.log(`📧 Would send error notification: ${errorNotification.subject}`);

return [{
  json: {
    ...$input.first().json,
    error_notification: errorNotification
  }
}];

// Get processing stats
const { processing_stats, completion_timestamp } = $input.first().json;

console.log(`✅ Enhanced Multi-Agent Call Center Analysis Workflow completed at ${completion_timestamp}`);
console.log(`📊 Final stats: ${processing_stats.calls_processed} calls processed, ${processing_stats.successful} successful, ${processing_stats.failed} failed, ${processing_stats.skipped} skipped`);

return [{
  json: {
    workflow_status: 'completed',
    completion_timestamp,
    processing_stats
  }
}];

// Format infrastructure validation error
const errorNotification = {
  subject: `❌ Infrastructure Validation Failed - ${new Date().toISOString()}`,
  body: `
  The Multi-Agent Call Center Analysis Workflow could not run because the required infrastructure is not properly set up.

  Please run the Infrastructure Setup and Validation Workflow first to create the necessary database tables and S3 bucket structure.
  `
};

console.log(`📧 Would send infrastructure validation error notification: ${errorNotification.subject}`);

return [{
  json: {
    error_notification: errorNotification,
    workflow_status: 'failed',
    completion_timestamp: new Date().toISOString()
  }
}];
